package io.github.isidorotrevino.planner.lab;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class TreeVerifierTest {
 @TempDir Path root;
 static byte[] bytes(String s){return s.getBytes(StandardCharsets.UTF_8);}
 Map<String,TreeVerifier.Artifact> expected(){return Map.of("dir/a.txt",TreeVerifier.Artifact.of(bytes("ok"),false));}
 void prepare()throws Exception{Files.createDirectory(root.resolve("tree"));Files.createDirectory(root.resolve("tree/dir"));Files.write(root.resolve("tree/dir/a.txt"),bytes("ok"));}
 @Test void exactFilesAndLocalRestorationObserveSameManifest()throws Exception{prepare();var a=TreeVerifier.files(root.resolve("tree"),expected(),false);var b=TreeVerifier.files(root.resolve("tree"),expected(),true);assertEquals(a.manifest(),b.manifest());assertEquals(1,a.files());assertEquals("d4.local-restoration.v1",b.method());}
 @Test void traversalAndGitPathsRejected(){for(var p:List.of("../x","/x","x/",".git/a","X/.GIT/config","x//y","x y","."))assertThrows(IllegalArgumentException.class,()->TreeVerifier.manifest(Map.of(p,TreeVerifier.Artifact.of(bytes("ok"),false))));}
 @Test void rejectsExtraFilesAndDirectories()throws Exception{prepare();Files.write(root.resolve("tree/extra"),bytes("x"));assertThrows(Exception.class,()->TreeVerifier.files(root.resolve("tree"),expected(),false));Files.delete(root.resolve("tree/extra"));Files.createDirectory(root.resolve("tree/empty"));assertThrows(Exception.class,()->TreeVerifier.files(root.resolve("tree"),expected(),false));}
 @Test void rejectsMissingAndChangedContent()throws Exception{prepare();Files.write(root.resolve("tree/dir/a.txt"),bytes("no"));assertThrows(Exception.class,()->TreeVerifier.files(root.resolve("tree"),expected(),false));Files.delete(root.resolve("tree/dir/a.txt"));assertThrows(Exception.class,()->TreeVerifier.files(root.resolve("tree"),expected(),false));}
 @Test void rejectsSymlinkAndHardlink()throws Exception{prepare();Files.move(root.resolve("tree/dir/a.txt"),root.resolve("outside"));Files.createSymbolicLink(root.resolve("tree/dir/a.txt"),root.resolve("outside"));assertThrows(Exception.class,()->TreeVerifier.files(root.resolve("tree"),expected(),false));Files.delete(root.resolve("tree/dir/a.txt"));Files.createLink(root.resolve("tree/dir/a.txt"),root.resolve("outside"));assertThrows(Exception.class,()->TreeVerifier.files(root.resolve("tree"),expected(),false));}
 @Test void rejectsExecutableMismatchAndOversizedManifest()throws Exception{prepare();Files.setPosixFilePermissions(root.resolve("tree/dir/a.txt"),Set.of(java.nio.file.attribute.PosixFilePermission.OWNER_READ,java.nio.file.attribute.PosixFilePermission.OWNER_EXECUTE));assertThrows(Exception.class,()->TreeVerifier.files(root.resolve("tree"),expected(),false));assertThrows(IllegalArgumentException.class,()->new TreeVerifier.Artifact(65537,"a".repeat(64),false));var many=new HashMap<String,TreeVerifier.Artifact>();for(int n=0;n<65;n++)many.put("f"+n,TreeVerifier.Artifact.of(bytes("ok"),false));assertThrows(IllegalArgumentException.class,()->TreeVerifier.manifest(many));}
 @Test void gitObjectsAndAncestryCheckedIndependently()throws Exception{try(var git=new TreeVerifier.GitStore(root)){var base=git.commit(Map.of("dir/a.txt",bytes("ok")),expected(),null);var next=git.commit(Map.of("dir/a.txt",bytes("ok")),expected(),base);assertEquals(TreeVerifier.manifest(expected()),git.verify(next,base,expected()).manifest());assertThrows(Exception.class,()->git.verify(next.substring(1),base,expected()));assertThrows(Exception.class,()->git.verify(base,next,expected()));assertThrows(Exception.class,()->git.verify(next,base,Map.of("dir/a.txt",TreeVerifier.Artifact.of(bytes("no"),false))));}}
 @Test void gitRejectsBlobAndModeSubstitution()throws Exception{try(var git=new TreeVerifier.GitStore(root)){assertThrows(Exception.class,()->git.commit(Map.of("dir/a.txt",bytes("no")),expected(),null));var base=git.commit(Map.of("dir/a.txt",bytes("ok")),expected(),null);assertThrows(Exception.class,()->git.verify(base,base,Map.of("dir/a.txt",TreeVerifier.Artifact.of(bytes("ok"),true))));}}
 @Test void parentDirectoryAliasesAndCollidingPathsRejected()throws Exception{prepare();Files.createSymbolicLink(root.resolve("alias"),root.resolve("tree"));assertThrows(Exception.class,()->TreeVerifier.files(root.resolve("alias/dir"),Map.of("a.txt",TreeVerifier.Artifact.of(bytes("ok"),false)),false));assertThrows(IllegalArgumentException.class,()->TreeVerifier.manifest(Map.of("a",TreeVerifier.Artifact.of(bytes("ok"),false),"a/b",TreeVerifier.Artifact.of(bytes("ok"),false))));}
 @Test void gitStoreConfigurationAndIndirectionAreRejected()throws Exception{try(var git=new TreeVerifier.GitStore(root)){var base=git.commit(Map.of("dir/a.txt",bytes("ok")),expected(),null);Path repo;try(var dirs=Files.list(root)){repo=dirs.filter(Files::isDirectory).findFirst().orElseThrow();}Files.writeString(repo.resolve("objects/info/alternates"),"/tmp\n");assertThrows(Exception.class,()->git.verify(base,base,expected()));Files.delete(repo.resolve("objects/info/alternates"));Files.writeString(repo.resolve("config"),"[core]\n hooksPath=/tmp\n");assertThrows(Exception.class,()->git.verify(base,base,expected()));}}

}
